import { SEED_CATEGORIES, SEED_INDICATORS } from "./indicators.ts";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

/** Idempotent seed SQL: re-running updates nothing that admins have edited. */
export function buildSeedSql(): string {
  const lines: string[] = [
    "-- GENERATED by `npm run seed:generate` from src/data/indicators.ts — do not edit by hand.",
    "-- Idempotent: existing rows (matched by code) are left untouched.",
    "begin;",
    "",
  ];
  for (const c of SEED_CATEGORIES) {
    lines.push(
      `insert into public.categories (code, name, name_en, color, sort_order) values (${q(c.code)}, ${q(c.name)}, ${q(c.nameEn)}, ${q(c.color)}, ${c.sortOrder}) on conflict (code) do nothing;`,
    );
  }
  lines.push("");
  for (const i of SEED_INDICATORS) {
    lines.push(
      `insert into public.indicators (code, category_id, title, description, recommended_evidence, required_image_count, required_video_count, sort_order) select ${q(i.code)}, c.id, ${q(i.title)}, ${q(i.description)}, ${q(i.recommendedEvidence)}, ${i.requiredImageCount}, ${i.requiredVideoCount}, ${i.sortOrder} from public.categories c where c.code = ${q(i.categoryCode)} on conflict (code) do nothing;`,
    );
  }
  lines.push("");
  const settings: Record<string, unknown> = {
    "school.name": "โรงเรียนบ้านโคกสูง",
    "school.area": "สำนักงานเขตพื้นที่การศึกษาประถมศึกษาศรีสะเกษ เขต 3",
    "system.name": "ระบบรวบรวมภาพและวิดีโอประกอบการนิเทศเปิดภาคเรียน",
    "system.name_en": "TeacherTemplate VTR Evidence Hub",
    "term.semester": "2",
    "term.academic_year": "2569",
    "upload.max_image_mb": 20,
    "upload.max_video_mb": 500,
    "upload.max_files": 20,
    "upload.allowed_types": ["image/jpeg", "image/png", "image/webp", "video/mp4", "video/quicktime", "video/webm"],
    "display.public_dashboard": true,
    "display.show_recent_submitters": false,
    "security.require_turnstile": true,
    "drive.root_folder_name": "VTR_นิเทศเปิดภาคเรียน_2_2569",
  };
  for (const [k, v] of Object.entries(settings)) {
    lines.push(
      `insert into public.system_settings (key, value) values (${q(k)}, ${q(JSON.stringify(v))}::jsonb) on conflict (key) do nothing;`,
    );
  }
  lines.push("", "commit;", "");
  return lines.join("\n");
}
